 const deleteStudent=async()=>{
  if(!isOwner){setError('Only the owner can delete students.');setDeleteConfirm(false);return}
  setDeletingStudent(true);setError('')
  try{
   const bucketPaths={}
   const addPath=(bucket,path)=>{if(!path)return;(bucketPaths[bucket]??=[]).push(path)}
   resources.forEach(r=>addPath('lesson-resources',r.file_path))
   assignments.forEach(a=>addPath('homework-files',a.attachment_path))
   submissionFiles.forEach(f=>addPath('homework-files',f.file_path))
   classworkAttachments.filter(a=>a.attachment_type==='file').forEach(a=>addPath(a.storage_bucket||'lesson-resources',a.file_path))
   for(const [bucket,paths] of Object.entries(bucketPaths)){const unique=[...new Set(paths.filter(Boolean))];if(unique.length)await supabase.storage.from(bucket).remove(unique)}
   const {error}=await supabase.from('students').delete().eq('id',id)
   if(error)throw error
   navigate('/students',{replace:true})
  }catch(e){setError(e.message||'Could not delete student.');setDeleteConfirm(false);setDeletingStudent(false)}
 }
