 const setCurriculumTopic=async(topic,current,curriculumTopicId=null)=>{setError('');if(!activeCourse)return;if(!current){const {error}=await supabase.from('topic_progress').insert({student_id:id,student_course_id:activeCourse.id,topic,status:'red',curriculum_topic_id:curriculumTopicId||null});if(error)setError(error.message);else load();return}if(current.status==='green'){const {error}=await supabase.from('topic_progress').delete().eq('id',current.id);if(error)setError(error.message);else load();return}const next=current.status==='red'?'amber':'green';const {error}=await supabase.from('topic_progress').update({status:next,updated_at:new Date().toISOString()}).eq('id',current.id);if(error)setError(error.message);else load()}

 const addTopic=async()=>{const topic=prompt('Topic name');if(!topic)return;const status=(prompt('Status: red, amber or green','amber')||'amber').toLowerCase();if(!['red','amber','green'].includes(status))return alert('Use red, amber or green.');const {error}=await supabase.from('topic_progress').upsert({student_id:id,student_course_id:activeCourse?.id||null,topic,status},{onConflict:'student_id,topic'});if(error)setError(error.message);else load()}
