 const normaliseLink=value=>{let v=(value||'').trim();if(!v)return null;if(!/^https?:\/\//i.test(v))v=`https://${v}`;try{const u=new URL(v);if(!['http:','https:'].includes(u.protocol))return null;return u.toString()}catch{return null}}
