 const uploadClassworkFiles=async(parentType,parentId,files,bucket,recipient={student_id:id,course_id:activeCourse?.id||null})=>{const rows=[];for(const file of files){if(file.size>25*1024*1024)throw new Error(`${file.name} is larger than 25 MB.`);const safe=file.name.replace(/[^a-zA-Z0-9._-]+/g,'-').slice(-100);const path=`${recipient.student_id}/${parentType}/${parentId}/${Date.now()}-${globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2)}-${safe}`;const {error:ue}=await supabase.storage.from(bucket).upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(ue)throw ue;rows.push({student_id:recipient.student_id,student_course_id:recipient.course_id||null,parent_type:parentType,parent_id:parentId,attachment_type:'file',title:file.name,file_path:path,original_name:file.name,mime_type:file.type||'application/octet-stream',file_size:file.size,storage_bucket:bucket})}if(rows.length){const {error}=await supabase.from('classwork_attachments').insert(rows);if(error)throw error}}
 const saveClassworkLinks=async(parentType,parentId,links,recipient={student_id:id,course_id:activeCourse?.id||null})=>{if(!links.length)return;const rows=links.map(link=>({student_id:recipient.student_id,student_course_id:recipient.course_id||null,parent_type:parentType,parent_id:parentId,attachment_type:'link',title:link.title||link.url,url:link.url}));const {error}=await supabase.from('classwork_attachments').insert(rows);if(error)throw error}
 const ensureRecipientTopic=async(recipient,topicName)=>{if(!topicName)return null;if(recipient.course_id===activeCourse?.id){const current=courseResourceTopics.find(t=>t.name.trim().toLowerCase()===topicName.trim().toLowerCase());if(current)return current.id}const {data:existing,error:ee}=await supabase.from('resource_topics').select('id').eq('student_course_id',recipient.course_id).ilike('name',topicName).limit(1);if(ee)throw ee;if(existing?.[0]?.id)return existing[0].id;const {data:created,error:ce}=await supabase.from('resource_topics').insert({student_id:recipient.student_id,student_course_id:recipient.course_id,name:topicName,position:999}).select('id').single();if(ce)throw ce;return created.id}
 const uploadResource=async()=>{setError('');const title=resourceTitle.trim().slice(0,160);if(!title){setError('Enter a material title.');return}if(!resourceFiles.length&&!resourceLinks.length){setError('Add at least one file or link.');return}const recipients=selectedRecipients.length?selectedRecipients:[{student_id:id,course_id:activeCourse?.id,name:s?.name}];if(!recipients.length){setError('Choose at least one student.');return}const topicName=resourceTopicId?(courseResourceTopics.find(t=>t.id===resourceTopicId)?.name||''):'';setResourceUploading(true);try{for(const recipient of recipients){const topicId=await ensureRecipientTopic(recipient,topicName);const {data:material,error:insertError}=await supabase.from('lesson_resources').insert({student_id:recipient.student_id,student_course_id:recipient.course_id||null,lesson_id:recipients.length===1&&recipient.student_id===id?resourceLessonId||null:null,title,file_path:null,original_name:null,mime_type:null,file_size:null,resource_topic_id:topicId}).select('id').single();if(insertError)throw insertError;try{await uploadClassworkFiles('material',material.id,resourceFiles,'lesson-resources',recipient);await saveClassworkLinks('material',material.id,resourceLinks,recipient)}catch(e){await supabase.from('lesson_resources').delete().eq('id',material.id);throw e}}setResourceTitle('');setResourceLessonId('');setResourceTopicId('');setResourceFiles([]);setResourceLinks([]);setSelectedRecipientCourseIds(activeCourse?.id?[activeCourse.id]:[]);setClassworkModal(null);await load()}catch(e){setError(e.message)}finally{setResourceUploading(false)}}
 const openResource=async resource=>{if(!resource.file_path)return;setError('');const {data,error}=await supabase.storage.from('lesson-resources').createSignedUrl(resource.file_path,900);if(error){setError(error.message);return}window.open(data.signedUrl,'_blank','noopener,noreferrer')}
 const openClassworkAttachment=async attachment=>{if(attachment.attachment_type==='link'){window.open(attachment.url,'_blank','noopener,noreferrer');return}const {data,error}=await supabase.storage.from(attachment.storage_bucket||'lesson-resources').createSignedUrl(attachment.file_path,900);if(error){setError(error.message);return}window.open(data.signedUrl,'_blank','noopener,noreferrer')}
 const deleteResourceNow=async resource=>{setError('');const ats=classworkAttachments.filter(x=>x.parent_type==='material'&&x.parent_id===resource.id);for(const bucket of [...new Set(ats.filter(x=>x.attachment_type==='file'&&x.file_path).map(x=>x.storage_bucket||'lesson-resources'))]){const paths=ats.filter(x=>(x.storage_bucket||'lesson-resources')===bucket&&x.file_path).map(x=>x.file_path);if(paths.length){const {error}=await supabase.storage.from(bucket).remove(paths);if(error){setError(error.message);return}}}if(resource.file_path){const {error:storageError}=await supabase.storage.from('lesson-resources').remove([resource.file_path]);if(storageError){setError(storageError.message);return}}if(ats.length){const {error}=await supabase.from('classwork_attachments').delete().in('id',ats.map(x=>x.id));if(error){setError(error.message);return}}const {error:dbError}=await supabase.from('lesson_resources').delete().eq('id',resource.id);if(dbError){setError(dbError.message);return}setClassworkModal(null);load()}

