 const deleteAssignmentNow=async assignment=>{setError('');const ats=classworkAttachments.filter(x=>x.parent_type==='assignment'&&x.parent_id===assignment.id);for(const bucket of [...new Set(ats.filter(x=>x.attachment_type==='file'&&x.file_path).map(x=>x.storage_bucket||'homework-files'))]){const paths=ats.filter(x=>(x.storage_bucket||'homework-files')===bucket&&x.file_path).map(x=>x.file_path);if(paths.length){const {error}=await supabase.storage.from(bucket).remove(paths);if(error){setError(error.message);return}}}if(assignment.attachment_path){const {error:storageError}=await supabase.storage.from('homework-files').remove([assignment.attachment_path]);if(storageError){setError(storageError.message);return}}if(ats.length){const {error}=await supabase.from('classwork_attachments').delete().in('id',ats.map(x=>x.id));if(error){setError(error.message);return}}const {error}=await supabase.from('assignments').delete().eq('id',assignment.id);if(error)setError(error.message);else{setClassworkModal(null);load()}}
 const deleteAssignment=assignment=>setClassworkModal({type:'deleteAssignment',assignment})
