 const regenerateCode=async()=>{if(!isOwner){setError('Only the owner can manage student access codes.');return}if(!confirm('Generate a new access code? The old code will stop working immediately.'))return;for(let i=0;i<12;i++){const code=`AA${String(Math.floor(Math.random()*10000)).padStart(4,'0')}`;const {error}=await supabase.from('students').update({access_code:code,access_code_active:true}).eq('id',id);if(!error){load();return}if(error.code!=='23505'){setError(error.message);return}}setError('Could not generate a unique access code. Please try again.')}
 const copyCode=async()=>{if(!isOwner){setError('Only the owner can view student access codes.');return}if(!s.access_code)return;try{await navigator.clipboard.writeText(s.access_code);alert('Access code copied.')}catch{prompt('Copy this access code',s.access_code)}}
 if(error&&!s)return <div className="errorBox">{error}</div>; if(!s||!snapshot||!viewStudent)return <div className="loading">Loading student…</div>
 const row={...snapshot,attendance}; const gap=Number(snapshot.progress)-Number(snapshot.expected_progress); const auto=hasAutomaticCurriculum(viewStudent); const curriculumNames=curriculumTopicKeys(viewStudent); const curriculumIds=new Set((viewStudent?.curriculum_rows||[]).map(r=>r.id)); const extraTopics=courseTopics.filter(t=>!(t.curriculum_topic_id&&curriculumIds.has(t.curriculum_topic_id))&&!curriculumNames.has(t.topic))
