 <div className="twoCol equal"><section className="panel assessmentPanel"><div className="panelHead"><div><h2>Assessments</h2><p>Organise tests, mocks and past papers into groups.</p></div><div className="panelHeadActions"><button className="textButton" onClick={createAssessmentGroup}>+ Create group</button><button className="primary smallBtn" onClick={addAssessment}>+ Add assessment</button></div></div>{(()=>{const groups=[...courseAssessmentGroups,{id:'uncategorised',name:'Other assessments'}].map(g=>({...g,items:courseAssessments.filter(a=>(a.assessment_group_id||'uncategorised')===g.id)})).filter(g=>g.items.length||g.id!=='uncategorised');return groups.length?<div className="assessmentGroups">{groups.map(g=>{const avg=g.items.length?Math.round(g.items.reduce((sum,a)=>sum+(Number(a.score)/Number(a.total)*100),0)/g.items.length):null;return <div className="assessmentGroup" key={g.id}><div className="assessmentGroupHead"><button className="assessmentGroupToggle" onClick={()=>setOpenAssessmentGroups(v=>({...v,[g.id]:!v[g.id]}))}><div><b>{g.name}</b><span>{g.items.length} assessment{g.items.length===1?'':'s'}{avg!=null?` · Average ${avg}%`:''}</span></div><strong>{openAssessmentGroups[g.id]?'−':'+'}</strong></button>{g.id!=='uncategorised'&&<button className="topicMenuButton" onClick={()=>manageAssessmentGroup(g)}>•••</button>}</div>{openAssessmentGroups[g.id]&&<div className="assessmentItems">{g.items.length?g.items.map(a=><div className="assessmentRow" key={a.id}><div className="assessmentRowMain"><div><b>{a.title}</b><span>{a.taken_on}{a.notes?` · ${a.notes}`:''}</span></div><strong>{Math.round(a.score/a.total*100)}%<small>{a.score}/{a.total}</small></strong></div><div className="assessmentActions"><button className="ghost smallBtn" onClick={()=>editAssessment(a)}>Edit</button>{courseAssessmentGroups.length>0&&<button className="textButton" onClick={()=>moveAssessment(a)}>Move</button>}<button className="textButton dangerText" onClick={()=>deleteAssessment(a)}>Delete</button></div></div>):<div className="empty compactEmpty">No assessments in this group yet.</div>}</div>}</div>})}</div>:<div className="empty">No assessments yet. Create a group such as Topic Tests, Past Papers or Mocks.</div>})()}</section><section className="panel"><div className="panelHead"><div><h2>Lesson log</h2><p>{activeCourse?.course?`${activeCourse.course} lessons for ${s.name}.`:`Lessons for ${s.name}.`}</p></div><button className="textButton" onClick={openLessonRecorder}>+ Record lesson</button></div>{courseLessons.length?courseLessons.slice(0,8).map(l=><div className="rowCard lesson" key={l.id}><div className="lessonRowContent"><b>{l.topic}</b><span>{l.lesson_date} · {l.attendance} · {l.duration_minutes||60} mins</span>{l.notes&&<p>{l.notes}</p>}{l.homework&&<div className="lessonHomework"><b>Homework</b><p>{l.homework}</p></div>}</div><div className="lessonRowActions"><button type="button" className="textButton" onClick={()=>editStudentLesson(l)}>Edit</button><button type="button" className="textButton dangerText lessonDeleteButton" onClick={()=>deleteLesson(l)}>Delete</button></div></div>):<div className="empty">No lessons recorded for this course yet.</div>}</section></div>
